public class Main {
    public static void main(String[] args) {

        // Try all 8 primitive types
        byte  b = 100;
        short s = 5000;
        int   i = 2026;
        long  l = 8_000_000_000L;
        float f = 3.14f;
        double d = 3.14159265;
        char  c = 'J';
        boolean flag = true;

        // Type casting
        int fromDouble = (int) d;   // 3
        double fromInt = i;         // 2026.0

        // Wrapper utility
        System.out.println(Integer.MAX_VALUE);       // 2147483647
        System.out.println(Integer.toBinaryString(i)); // binary of 2026
        System.out.println(Character.isLetter(c));   // true

        System.out.println("byte="+b+" short="+s+" int="+i);
        System.out.println("long="+l+" float="+f+" double="+d);
        System.out.println("char="+c+" boolean="+flag);
        System.out.println("(int)3.14159 = " + fromDouble);
    }
}
